#include "native/costumes.hpp"
#include <algorithm>
namespace rosh {
static int class_index(int profession){int family=profession/100*100;int all[]={100,200,300,400,500,600,800};for(int i=0;i<7;i++)if(all[i]==family)return i;throw std::runtime_error("Classe nao suportada pelo traje");}
CashChoices::CashChoices(Sqlite&db,Content&content,Inventory&inventory):db_(db),inventory_(inventory),policy_(content.get("data/starter_costume_choices.json")),rules_(content.get("data/native_item_rules.json")){
 db_.exec("CREATE TABLE IF NOT EXISTS native_cash_piece_boxes(uid INTEGER PRIMARY KEY,eid INTEGER NOT NULL,target_item INTEGER NOT NULL,event_key TEXT NOT NULL UNIQUE)");
 db_.exec("CREATE TABLE IF NOT EXISTS native_costume_choices(source_uid INTEGER PRIMARY KEY,eid INTEGER NOT NULL,choice INTEGER NOT NULL,result TEXT NOT NULL);CREATE TABLE IF NOT EXISTS native_costume_boxes(source_uid INTEGER PRIMARY KEY,eid INTEGER NOT NULL,result TEXT NOT NULL);CREATE TABLE IF NOT EXISTS item_custom_affixes(uid INTEGER NOT NULL,layer TEXT NOT NULL,position INTEGER NOT NULL,stat TEXT NOT NULL,value REAL NOT NULL,PRIMARY KEY(uid,layer,position))");
}
ItemInstance CashChoices::instance(std::uint32_t eid,std::uint32_t uid){for(bool equipped:{false,true})for(auto&item:inventory_.items(eid,equipped))if(item.uid==uid){if(item.quantity!=1||(item.expires&&*item.expires<=now()))throw std::runtime_error("Peca temporaria expirada ou quantidade invalida");if(!equipped)return inventory_.owned(eid,item.slot,item.item,now());return item;}throw std::runtime_error("Peca ou caixa nao pertence ao personagem");}
std::optional<std::uint32_t> CashChoices::catalog_target(const ItemInstance&item){
 if(item.item<1000900000||item.item>=1000900028)return {};
 auto rows=db_.query("SELECT target_item FROM native_cash_piece_boxes WHERE uid=?",{std::int64_t(item.uid)});
 if(rows.size()!=1)throw std::runtime_error("Caixa de traje sem recibo de compra");
 auto target=rows[0].at("target_item").get<std::uint32_t>();auto rule=rules_.at(std::to_string(target));int cls=rule.value("class",0),slot=rule.value("slot",0);
 if(rule.value("kind",0)!=1||slot<26||slot>29||item.item!=1000900000u+class_index(cls)*4+slot-26)throw std::runtime_error("Recibo da caixa nao corresponde a peca");return target;
}
std::uint32_t CashChoices::grant_catalog_box(std::uint32_t eid,std::uint32_t target,const std::string&event){
 Transaction tx(db_);auto prior=db_.query("SELECT uid,eid,target_item FROM native_cash_piece_boxes WHERE event_key=?",{event});
 if(!prior.empty()){if(prior[0].at("eid")!=eid||prior[0].at("target_item")!=target)throw std::runtime_error("Recibo de caixa reutilizado");auto uid=prior[0].at("uid").get<std::uint32_t>();tx.commit();return uid;}
 auto rule=rules_.at(std::to_string(target));int cls=rule.value("class",0),slot=rule.value("slot",0);if(rule.value("kind",0)!=1||slot<26||slot>29)throw std::runtime_error("A caixa exige uma peca de traje cash");
 auto box=1000900000u+class_index(cls)*4+slot-26;std::set<std::uint32_t>before;for(auto&i:inventory_.items(eid))before.insert(i.uid);
 int seconds=rule.value("duration",0);if(seconds>0)inventory_.grant_timed_once(eid,box,1,seconds,event);else inventory_.grant_once(eid,{{box,1}},event);
 std::uint32_t uid=0;for(auto&i:inventory_.items(eid))if(i.item==box&&!before.count(i.uid)){if(uid)throw std::runtime_error("Entrega de caixa ambigua");uid=i.uid;}
 if(!uid)throw std::runtime_error("Caixa nao foi entregue");db_.exec("INSERT INTO native_cash_piece_boxes VALUES(?,?,?,?)",{std::int64_t(uid),std::int64_t(eid),std::int64_t(target),event});tx.commit();return uid;
}
int CashChoices::part(int cls,const ItemInstance&item,bool box)const{int index=class_index(cls);if(box){if(item.item<180148u+index*4||item.item>=180152u+index*4)throw std::runtime_error("Caixa de outra classe");return (item.item-180148)%4;}auto rule=rules_.value(std::to_string(item.item),Json::object());int slot=rule.value("slot",0),family=cls/100*100,required=rule.value("class",0);if(rule.value("kind",0)!=1||slot<26||slot>29||(required&&required/100*100!=family))throw std::runtime_error("Item nao e uma peca cash desta classe");return slot-26;}
Json CashChoices::attributes(int cls,int piece,int option)const{if(option!=1&&option!=2)throw std::runtime_error("Escolha apenas a opcao1 ou2");auto rows=policy_.at("options").at(std::to_string(26+piece)).at(option-1);bool magical=false;for(auto family:policy_.at("magical_classes"))if(family==cls/100*100)magical=true;for(auto&row:rows)if(row[0]=="class_speed")row[0]=magical?"cast_speed":"attack_speed";return rows;}
Json CashChoices::preview(std::uint32_t eid,std::uint32_t uid,int cls){auto item=instance(eid,uid);auto selected=catalog_target(item);auto definition=item;if(selected)definition.item=*selected;bool box=!selected&&item.item>=180148&&item.item<180176;int piece=part(cls,definition,box);Json labels=Json::array();static const std::map<std::string,std::string>names={{"physical_attack_flat","Ataque fisico"},{"magic_attack_flat","Ataque magico"},{"physical_defense_flat","Defesa fisica"},{"magic_defense_flat","Defesa magica"},{"critical_chance_flat","Chance critica"},{"cast_speed","Velocidade de conjuracao"},{"attack_speed","Velocidade de ataque"},{"move_speed","Velocidade de movimento"},{"max_hp","HP maximo"}};for(int option=1;option<=2;option++){std::string label="Opcao "+std::to_string(option)+": ";bool first=true;for(auto&row:attributes(cls,piece,option)){auto stat=row[0].get<std::string>();if(!first)label+=", ";first=false;label+=names.at(stat)+" +"+row[1].dump();if(stat.find("_flat")==std::string::npos)label+="%";}labels.push_back(label);}return {{"cmd","asmara.choice"},{"uid",uid},{"name",inventory_.name(selected.value_or(item.item))},{"speech","Escolha uma configuracao para esta peca. A outra opcao nao sera entregue. Validade preservada."},{"options",labels}};}
std::vector<std::uint32_t> CashChoices::open(std::uint32_t eid,int slot,std::uint32_t iid,int cls){
 int index=class_index(cls);if(iid!=999000303&&iid!=static_cast<std::uint32_t>(180141+index))throw std::runtime_error("Caixa de outra classe");Transaction tx(db_);auto item=inventory_.owned(eid,slot,iid,now());if(item.quantity!=1)throw std::runtime_error("A caixa exige uma instancia individual");auto end=static_cast<std::uint32_t>(now()+policy_.at("seconds").get<int>());if(item.expires)end=std::min(end,*item.expires);inventory_.consume(eid,item,1,"open-box");std::vector<std::uint32_t>boxes;for(int piece=0;piece<4;piece++){auto id=180148+index*4+piece;auto target=inventory_.insert(eid,id,1);auto result=inventory_.owned(eid,target,id,now());inventory_.trace_derivation(item.uid,result,eid);db_.exec("INSERT INTO reward_instances VALUES(?,?,?,?,?)",{std::int64_t(result.uid),std::int64_t(eid),std::int64_t(id),std::int64_t(end),std::string("starter-piecebox")});boxes.push_back(id);}db_.exec("INSERT INTO native_costume_boxes VALUES(?,?,?)",{std::int64_t(item.uid),std::int64_t(eid),Json(boxes).dump()});tx.commit();return boxes;
}
Json CashChoices::choose(std::uint32_t eid,std::uint32_t uid,int cls,int option){
 if(option!=1&&option!=2)throw std::runtime_error("Escolha uma opcao valida");Transaction tx(db_);auto prior=db_.query("SELECT eid,choice,result FROM native_costume_choices WHERE source_uid=?",{std::int64_t(uid)});if(!prior.empty()){if(prior[0].at("eid")!=eid||prior[0].at("choice")!=option)throw std::runtime_error("Esta peca ja recebeu outra escolha");auto result=Json::parse(prior[0].at("result").get<std::string>());tx.commit();return result;}
 auto item=instance(eid,uid);auto selected=catalog_target(item);auto definition=item;if(selected)definition.item=*selected;bool box=!selected&&item.item>=180148&&item.item<180176;int piece=part(cls,definition,box);auto rows=attributes(cls,piece,option);std::string layer="costume_choice";
 if(selected){auto expiry=item.expires;auto target=*selected;if(!expiry&&rules_.at(std::to_string(target)).value("duration",0)>0)throw std::runtime_error("Prazo de compra ausente");auto parent=item.uid;inventory_.consume(eid,item,1,"open-box");auto slot=inventory_.insert(eid,target,1);
 item=inventory_.owned(eid,slot,target,now());inventory_.trace_derivation(parent,item,eid);if(expiry)db_.exec("INSERT INTO reward_instances VALUES(?,?,?,?,?) ON CONFLICT(uid) DO UPDATE SET expires_at=excluded.expires_at,source=excluded.source",{std::int64_t(item.uid),std::int64_t(eid),std::int64_t(target),std::int64_t(*expiry),std::string("cash-box-choice")});layer="costume_choice";}
 else if(box){auto end=static_cast<std::uint32_t>(now()+policy_.at("seconds").get<int>());if(item.expires)end=std::min(end,*item.expires);auto parent=item.uid;inventory_.consume(eid,item,1,"open-box");auto id=policy_.at("parts").at(std::to_string(cls/100*100)).at(piece).get<std::uint32_t>();auto slot=inventory_.insert(eid,id,1);item=inventory_.owned(eid,slot,id,now());inventory_.trace_derivation(parent,item,eid);db_.exec("INSERT INTO reward_instances VALUES(?,?,?,?,?)",{std::int64_t(item.uid),std::int64_t(eid),std::int64_t(id),std::int64_t(end),std::string("starter-choice")});layer="starter";}
 else if(!db_.query("SELECT 1 FROM item_custom_affixes WHERE uid=? LIMIT 1",{std::int64_t(item.uid)}).empty())throw std::runtime_error("Peca ja personalizada; atributos anteriores preservados");
 int position=0;for(auto&row:rows)db_.exec("INSERT INTO item_custom_affixes VALUES(?,?,?,?,?)",{std::int64_t(item.uid),layer,std::int64_t(position++),row[0].get<std::string>(),row[1].get<double>()});Json result={{"uid",item.uid},{"item",item.item},{"option",option},{"attributes",rows}};db_.exec("INSERT INTO native_costume_choices VALUES(?,?,?,?)",{std::int64_t(uid),std::int64_t(eid),std::int64_t(option),result.dump()});tx.commit();return result;
}
}
